# ---------- ATTACK-005: commit_sha older than the predecessor's; on an unreachable branch; equal; abbreviated; uppercase
{
fresh a005; OLD=$(git rev-parse HEAD~2); PRED=$(grep '^commit_sha' changes/c1/06-verification/handoff.yml | cut -d' ' -f2)
echo "predecessor (verify) commit_sha $PRED; initial commit $OLD"
