echo "== 5c: commit_sha equal to the predecessor's (allowed by the rule)"; $B/complete.rb $R evaluate $PRED; git add -A; git commit -qm "evaluate complete (equal)"; run $B/sf gate evaluate | grep -E 'lineage|FAIL|PASS'
echo "== 5d: abbreviated 7-char and uppercase commit_sha"; H=$(git rev-parse HEAD); $B/complete.rb $R evaluate $H; perl -pi -e "s/^commit_sha: .*/commit_sha: ${H:0:7}/" changes/c1/07-evaluation/handoff.yml; run $B/sf gate evaluate | grep -E 'lineage|commit_sha|FAIL|PASS'; perl -pi -e "s/^commit_sha: .*/commit_sha: $(echo $H | tr a-f A-F)/" changes/c1/07-evaluation/handoff.yml; run $B/sf gate evaluate | grep -E 'lineage|commit_sha|FAIL|PASS'
echo "== 5e: predecessor's own commit_sha is garbage (hand-committed): lineage of the successor"; git checkout -q -- changes/c1; $B/complete.rb $R evaluate HEAD; perl -pi -e 's/^commit_sha: .*/commit_sha: deadbeef/' changes/c1/06-verification/handoff.yml; git add -A; git commit -qm "bad predecessor"; run $B/sf gate evaluate | grep -E 'lineage|predecessor|FAIL|PASS'; run $B/sf gate verify | grep -E 'lineage|commit_sha|FAIL|PASS'
echo "== 5f: commit_sha is a later commit than the one the phase was committed in (a future commit on the same branch)"; git checkout -q -- changes/c1; git reset -q --hard HEAD~1; $B/complete.rb $R evaluate HEAD; git add -A; git commit -qm "evaluate complete"; echo x > note.txt; git add note.txt; git commit -qm later; L=$(git rev-parse HEAD); perl -pi -e "s/^commit_sha: .*/commit_sha: $L/" changes/c1/07-evaluation/handoff.yml; run $B/sf gate evaluate | grep -E 'lineage|current|FAIL|PASS'
} > $OUT/attack-005.txt 2>&1
